/* Detailed rehearsal content. Each numbered PDF row has a stable source ID.
 * The flow is a practical learning sequence, not an asserted faculty grading order. */
(function (root, factory) {
  const api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  else { root.NRS114_CHECKOFF_DETAILS = api; api.apply(root.NRS114_SKILLS); }
})(typeof window === 'object' ? window : this, function () {
  'use strict';
  const R = (prefix, pages, labels, section, kind = 'row') => labels.map((label, i) => ({ id: prefix + '.' + (i + 1), page: String(pages[i]), label, location: section + ' ' + (i + 1), kind }));
  const T = (key, phase, title, action, why, covers = [], options = {}) => Object.assign({ key, phase, title, action, why, covers, safety: false }, options);
  const details = {};

  details.ivpush = {
    scene: 'A patient has an IV push medication due through a saline lock. Your lab supplies the actual order, drug reference, flush plan and access device. Say what you check and demonstrate the connections and timing.',
    rows: [
      ...R('iv.prep', [52,52], ['Review the order against EMR/MAR and instructions', 'Calculate and prepare the required dose'], 'Preparation row'),
      ...R('iv.bed', [52,52,53,53,53,53,53,53,53,53,'53–54',54,54,54], ['Two identifiers and MAR/wristband comparison', 'Allergy band, allergy history and reaction severity', 'Ask patient to report IV pain, swelling or burning', 'Hand hygiene and nonsterile gloves', 'Alcohol port scrub for 15 seconds and allow drying', 'Remove flush air, release extension clamp and check patency; printed 3–5 mL', 'Needleless medication syringe connection', 'Timer/second-hand or push-pause wording for injection', 'Remove air from next saline syringe and reconnect', 'Postflush at medication rate; printed 3–5 mL', 'Morphine example: 1 mL over 1 minute and initial flush timing', 'Furosemide example: 4 mL over 2 minutes and initial flush timing', 'Dispose of syringes/filter needles in puncture-proof receptacles', 'Document per agency protocol'], 'Bedside row'),
      ...R('iv.objective', [52,52,52,52], ['Accurate administration to prevent harm', 'Recognize sensitivity to adverse IV medication effects', 'Review creatinine and other relevant levels', 'Printed lowest-dose/titration wording and last-dose assessment'], 'Objective', 'objective')
    ],
    notes: [
      { covers: ['iv.objective.1'], text: 'Accuracy includes the right patient, drug, dose, formulation, route, timing and documented response.' },
      { covers: ['iv.objective.2'], text: 'Explain the expected effect, adverse effects, monitoring and emergency response for the actual drug.' },
      { covers: ['iv.objective.3'], text: 'Know which renal/laboratory findings matter to this drug and resolve unsafe results before administration.' },
      { covers: ['iv.objective.4'], text: 'Check the last dose. Give the prescribed dose; use lowest-dose/titration language only when the actual order/protocol authorizes titration.' }
    ],
    steps: [
      T('order','Prepare','Review the order and MAR','Compare the drug, dose, formulation, route, due time, indication and special instructions in the order and MAR. Check when the last dose was actually given.','A duplicated or unsuitable dose is not made safe by a correct calculation.',['iv.prep.1'],{safety:true}),
      T('assess-drug','Prepare','Check the drug-specific assessment','Check allergies, contraindications and the vital signs/laboratory results required for this drug, including renal function when relevant. Clarify abnormal findings or an unclear order.','Drug clearance and patient condition can change the safety of the same dose.',[],{safety:true}),
      T('reference','Prepare','Find the actual administration instructions','Verify that this formulation may be given IV push. Find compatibility, concentration, required dilution, exact administration time and monitoring in the approved drug reference.','Every IV push drug does not use the same dilution or rate.',[],{safety:true}),
      T('explain-timing','Prepare','Explain both printed timing examples','For the manual’s morphine example, 1 mL over 1 minute means 1 mL/min. For its furosemide example, 4 mL over 2 minutes means 2 mL/min, so 1 mL takes 30 seconds. Explain why the drug-containing flush portion must preserve that delivery rate.','These are calculation examples, not standing drug doses, dilution instructions, dead-space volumes or universal flush rules.',['iv.bed.11','iv.bed.12'],{note:'Use the actual order, product reference and tubing volume. Explain these examples when asked; do not interrupt urgent monitoring to recite them.'}),
      T('calculate','Prepare','Calculate and prepare the dose','Calculate the prescribed dose and volume; complete required independent checks. Compare the label with the MAR during selection/preparation and before administration; check expiry and product integrity.','This connects the order with the product and the amount in the syringe.',['iv.prep.2'],{safety:true}),
      T('label','Prepare','Label the medication and gather supplies','Clean hands, prepare aseptically and label the medication syringe. Do not use a manufacturer-prefilled flush syringe to mix medication. Gather the compatible flushes, connector antiseptic, timer, gloves and disposal container.','A medication syringe must not be mistaken for an ordinary saline flush.',[]),
      T('identify','At the bedside','Identify the patient','Use two approved identifiers such as stated name and date of birth, then compare the wristband with the MAR. Explain the procedure and provide privacy.','The final identification check happens with this patient and this MAR.',['iv.bed.1'],{say:'Please tell me your full name and date of birth. I am checking these against your medication record.',safety:true}),
      T('allergy','At the bedside','Confirm allergies and the reaction','Check the allergy band/record and ask what happened and how severe the reaction was. Resolve a relevant allergy before giving the drug.','An allergy name without its reaction history may omit important risk.',['iv.bed.2'],{say:'What medication allergies do you have, and what happened when you took them?',safety:true}),
      T('report','At the bedside','Teach the patient what to report','Ask the patient to report pain, burning, swelling or leaking at the IV, and any new symptoms during administration.','The patient may detect a complication before you can see it.',['iv.bed.3'],{say:'Tell me immediately if this burns, hurts, swells, or makes you feel suddenly unwell.'}),
      T('hands','At the bedside','Clean hands and put on gloves','Perform hand hygiene and put on clean nonsterile gloves and any additional exposure precautions. Position the bed/work area safely.','Gloves do not replace hand hygiene.',['iv.bed.4']),
      T('trace','At the bedside','Trace and assess the access','Trace the intended line to the patient. Inspect the site and device, ask about discomfort, and manage a running infusion using the compatibility/access plan.','The right syringe can still be connected to the wrong or compromised line.',[],{safety:true}),
      T('scrub','Administer','Disinfect the connector and let it dry','Scrub the access port with the approved antiseptic and required friction/contact time, then let it dry completely. The manual specifies an alcohol scrub for 15 seconds; follow the actual connector/antiseptic protocol.','Connecting before adequate disinfection and drying can carry organisms into the access.',['iv.bed.5'],{safety:true}),
      T('flush-ready','Administer','Prepare the patency flush and release the clamp','Remove air from the compatible flush as its instructions require without contaminating its tip. Release the saline-lock extension clamp as appropriate for the device.','A closed clamp or air-filled preparation can interfere with safe access.',['iv.bed.6']),
      T('patency','Administer','Check patency without force','Connect aseptically and use the device/patient-specific flush plan to assess patency. The manual lists 3–5 mL; verify the actual volume and syringe size. Stop for resistance, pain, swelling or leakage.','Forcing a flush can worsen an access complication.',['iv.bed.6'],{safety:true}),
      T('connect-drug','Administer','Connect the medication syringe','Disconnect the first flush as directed, disinfect between connections as required, and attach the needleless medication syringe aseptically.','The connector and syringe tip must remain protected through each connection.',['iv.bed.7'],{safety:true}),
      T('time-drug','Administer','Time the medication delivery','Give the prescribed volume over the verified drug-specific time using a timer/second hand. Observe the site and patient throughout. Push-pause flushing does not establish a medication rate.','A rapid delivery can cause an unintended bolus.',['iv.bed.8'],{safety:true}),
      T('connect-flush','Administer','Prepare and connect the final flush','Prepare the next prescribed compatible flush without air or tip contamination; disinfect and connect according to the access protocol.','The flush must remain a safe compatible preparation.',['iv.bed.9']),
      T('clear-dose','Administer','Clear medication in the line at the safe rate','Flush the drug-containing dead space at the medication’s required delivery rate, then complete flushing/locking using the actual device protocol and volume. The manual lists a 3–5 mL postflush.','Residual medication in tubing is still part of the dose.',['iv.bed.10'],{safety:true}),
      T('dispose','Finish','Restore the line and dispose safely','Restore the ordered compatible infusion or lock the device as directed. Dispose of syringes and any filter needles in the designated puncture-proof receptacles according to policy. Remove gloves and clean hands.','Line management and disposal are part of finishing the procedure.',['iv.bed.13']),
      T('record','Finish','Reassess and document','Reassess the intended effect/adverse effects and IV site. Leave the patient comfortable with a low locked bed and call light. Record actual drug, dose, route/access, time, required assessments, response and any withheld dose/escalation.','The record should describe actual delivery and response.',['iv.bed.14'])
    ]
  };

  details.blood = {
    scene: 'An ordered component is ready for transfusion. You have a qualified checker and the facility’s administration setup. Rehearse each patient/document/unit comparison explicitly rather than saying only “check the blood.”',
    rows: [
      ...R('blood.row',[55,55,55,55,56,56,56,56,56,56,56,'56–57',57,57,57,57,57,57,58,58,58,58,58,58,58,'58–59'],['Order: indication, rate and premedications','Signed informed consent','Assess/reinforce patient understanding','Prescribed pretransfusion medication','Obtain component from blood bank per policy','Gloves when handling product','Qualified second-person check: order, consent, labs and donor type','Stated name/date of birth against blood-bank form','Patient name/hospital ID on wristband','Patient name/hospital ID on component-associated form','Unit number: blood-bank form against bag','Recipient/component blood-type comparison','Any discrepancy: contact blood bank and do not administer','Both qualified staff sign after verification','Actual transfusion start date/time on form','Retain attached form and label tubing date/time','Close administration-set clamps','Uncover saline port and one Y-set spike aseptically','Spike saline and open its clamp; protect blood-side spike','Fill chamber about halfway/filter covered and prime with saline','Baseline vital signs before transfusion','Prescribed drip rate','Printed first-five-minute bedside observation then vital signs','Vital signs at 15 minutes, 30 minutes, then hourly','Completion: blood-side clamp, saline flush, appropriate disposal','Second unit using same set only if facility protocol permits'],'Row'),
      ...R('blood.objective',[55,55,55,55],['Demonstrate blood administration','Explain indications for component use','Explain patient/donor/type verification','Discuss transfusion reactions and their impact'],'Objective','objective')
    ],
    notes: [
      {covers:['blood.objective.1'],text:'Demonstrate the complete setup, bedside verification, start, monitoring and finish using the lab equipment.'},
      {covers:['blood.objective.2'],text:'Explain why this component was prescribed: red cells support oxygen-carrying capacity; platelets address an appropriate platelet problem; plasma replaces indicated clotting factors. Match the actual indication and laboratory findings.'},
      {covers:['blood.objective.3'],text:'State each patient, document, unit and compatibility comparison separately. Compatibility does not always require identical ABO labels.'},
      {covers:['blood.objective.4'],text:'Know concerning symptoms, stop immediately for a suspected reaction, and explain the reaction pathway and possible serious consequences.'}
    ],
    steps: [
      T('order','Prepare','Read the transfusion order','Verify indication, component, amount, rate and any actual premedication order against the record.','The order establishes what component and administration plan are intended.',['blood.row.1'],{safety:true}),
      T('consent','Prepare','Verify informed consent','Confirm that the required informed consent is completed and signed; resolve a missing or unclear consent before proceeding.','A correct product check does not replace consent.',['blood.row.2'],{safety:true}),
      T('patient','Prepare','Identify, assess and teach','Use hand hygiene/two identifiers, assess prior reactions/allergies and current status, and assess the patient’s understanding. Explain the procedure and reinforce what to report.','Baseline symptoms and understanding help distinguish a new reaction.',['blood.row.3'],{say:'Call me immediately for chills, itching, back or chest pain, trouble breathing, or feeling suddenly unwell.'}),
      T('premed','Prepare','Give premedication only if ordered','Give prescribed pretransfusion medication with the normal medication checks and required timing/assessment.','Premedication is not an automatic requirement for every transfusion.',['blood.row.4'],{conditional:true}),
      T('access','Prepare','Prepare access and record baseline observations','Assess suitable patent IV access and fluid-overload risk. Obtain and record baseline vital signs and relevant pre-existing symptoms before starting, within the facility’s allowed interval.','You need a comparison baseline and a ready safe access.',['blood.row.21'],{safety:true}),
      T('collect','Prepare','Obtain the component when ready to start','Collect/receive the prescribed component from the blood bank under the facility’s identification, transport and time-limit policy.','Do not collect it before you can safely begin.',['blood.row.5']),
      T('ppe','Verify at the bedside','Use gloves and exposure precautions','Perform hand hygiene and wear gloves to handle the blood product; add other exposure precautions as required.','The component is handled with standard blood-exposure precautions.',['blood.row.6']),
      T('second-check','Verify at the bedside','Complete the qualified checker review','With the required qualified second staff member or approved verification process, recheck the order, consent, relevant labs and donor/component type at the bedside. The printed checklist calls for another qualified staff member.','A memory check away from the patient does not complete bedside verification.',['blood.row.7'],{safety:true}),
      T('stated-id','Verify at the bedside','Compare stated name and date of birth','Ask the patient, if able, to state their full name and date of birth; compare both with the blood-bank form. Use the approved identification process if the patient cannot respond.','The patient’s statement is one part of a document-to-patient identification check.',['blood.row.8'],{safety:true}),
      T('band-id','Verify at the bedside','Read the wristband identifiers','Read the patient’s name and hospital identification number on the wristband and compare with the transfusion documentation.','Room/bed number is not a patient identifier.',['blood.row.9'],{safety:true}),
      T('form-id','Verify at the bedside','Compare the attached patient form','Compare the patient name and hospital ID on the form associated with the actual component against the wristband/records.','The attached form must belong to this patient and this unit.',['blood.row.10'],{safety:true}),
      T('unit-id','Verify at the bedside','Compare the unit identification numbers','Compare the unit number on the blood-bank form with the number printed on the component container.','A correct patient name does not rule out a wrong-unit error.',['blood.row.11'],{safety:true}),
      T('compatibility','Verify at the bedside','Check blood-type compatibility and product integrity','Compare recipient/component blood types and the compatibility testing/authorization, then verify expiry and inspect integrity. Confirm suitability under the blood-bank rules rather than requiring identical labels in every case.','A compatible authorized component is the goal.',['blood.row.12'],{safety:true}),
      T('mismatch','Verify at the bedside','State the mismatch stop rule','For any discrepancy or questionable product, do not start. Contact the blood bank promptly and resolve it before administration; do not alter paperwork to make it match.','Every required check must be reconciled.',['blood.row.13'],{safety:true,conditional:true}),
      T('sign','Verify at the bedside','Complete both verification signatures','Once the checks agree, both required qualified checkers sign/complete the approved verification record.','A signature records a completed check, not one planned for later.',['blood.row.14']),
      T('label','Set up and start','Retain the form and label the tubing','Keep the required form with the component. Check the administration-set package/integrity, open it without contaminating connections, and label the tubing with date/time according to policy.','The component and administration record must remain traceable.',['blood.row.16']),
      T('clamps','Set up and start','Close the set clamps','Select the approved filtered blood set and close its clamps before spiking/priming.','This controls flow during preparation.',['blood.row.17']),
      T('uncover','Set up and start','Protect the saline port and spike','Remove the protective covers from the compatible 0.9% saline container port and one Y-set spike without contaminating either connection.','Aseptic connections protect the fluid path.',['blood.row.18']),
      T('saline','Set up and start','Spike the saline side','Insert the saline-side spike and open the correct saline clamp for priming. Keep the blood-side spike covered and its clamp closed until needed.','The other branch must remain protected and controlled.',['blood.row.19']),
      T('prime','Set up and start','Fill the chamber and prime','Gently compress/fill the drip chamber to the set’s specified level—printed about halfway with the filter covered—and prime with compatible saline, clearing air.','The actual filter/set instructions determine the working fluid level.',['blood.row.20']),
      T('start','Set up and start','Connect, trace and start at the prescribed initial rate','For the manual’s Y-set, aseptically spike the blood component and manage/prime the blood branch and its clamps according to the set instructions. Disinfect the assessed access, connect aseptically, trace the path and start at the ordered initial slow rate. Confirm flow and assess the patient/site.','Correct setup and an observed start are needed after verification.',['blood.row.22'],{safety:true}),
      T('start-time','Set up and start','Record the actual start date/time','Enter when the component actually began on the transfusion form/electronic record.','Recording it before administration could misstate the exposure and timing.',['blood.row.15']),
      T('early-watch','Monitor','Stay for early observation','Observe closely for the first 15 minutes of each component, remaining at bedside as policy requires. The printed row says first five minutes; do not use five minutes as the complete early observation period.','Severe reactions can begin early.',['blood.row.23'],{safety:true,note:'Ask faculty to reconcile the five-minute printed row with the current 15-minute early-observation plan.'}),
      T('observations','Monitor','Repeat observations and assess for reactions','Check and record vital signs at the prescribed times. The manual lists 15 minutes, 30 minutes and hourly; current guidance includes baseline, 15 minutes, completion and at least hourly, with more checks as needed.','Symptoms require immediate action rather than waiting for a scheduled check.',['blood.row.24'],{safety:true}),
      T('react','Monitor','State and apply the reaction response','If a reaction is suspected, stop the component immediately, assess/support ABCs, get appropriate help and follow the reaction pathway. If stable, continue only under the ordered rate/monitoring plan and component time limit.','Finishing the component must not take priority over a new adverse response.',[],{safety:true,conditional:true}),
      T('finish','Finish','Manage completion and the saline flush','After the unit is delivered and according to the set instructions, close the blood branch and open compatible saline to clear the set if directed. Reassess and record completion observations and delivered volume.','Clearing residual blood and reassessment complete the actual administration.',['blood.row.25']),
      T('next-unit','Finish','Check the plan for a second unit','If another unit is ordered, repeat the full verification and monitoring process. Reuse the set only when its permitted duration/product/facility policy allows; otherwise replace it.','A second bag is a new component exposure, not an exemption from checks.',['blood.row.26'],{conditional:true}),
      T('dispose','Finish','Dispose, document and leave the patient safe','Dispose of the empty component/set in the designated receptacles per policy, remove gloves and clean hands. Record the unit, times, observations, volume and response; ensure patient comfort/call light and delayed-reaction teaching. Preserve products instead of routine disposal if a reaction investigation is required.','Traceability and continuing observation extend beyond the empty bag.',['blood.row.25'])
    ]
  };

  details.reaction = {
    scene: 'During a transfusion the patient develops new concerning symptoms. Respond immediately. Support, escalation and investigation can occur together with help; the flow below is a rehearsal aid, not a forced serial resuscitation order.',
    rows: R('reaction.row',[60,60,60,60,60,60,'60–61',61,61,61,61],['Stop transfusion immediately for suspected reaction','Vital signs and heart/breath-sound assessment','Prompt physician notification after stopping/assessment','Do not flush attached blood tubing','Disconnect blood administration set from IV catheter','Maintain IV access with new saline infusion/new tubing','Bag, set and attached blood-bank form to blood bank in biohazard transport','Fresh blood specimen from opposite extremity as directed','Urine specimen under agency policy','Administer prescribed reaction medication','Continue frequent vital-sign monitoring'],'Row'),
    notes: [],
    steps: [
      T('stop','Immediate response','Stop the transfusion','Stop the component immediately for a suspected reaction. Stay with the patient and call appropriate help; activate emergency response for deterioration.','Further exposure can worsen the event.',['reaction.row.1'],{say:'I am stopping the transfusion and getting help while I check your breathing and circulation.',safety:true}),
      T('assess','Immediate response','Assess and support the patient','Assess ABCs, mental status and vital signs; auscultate heart and breath sounds. Provide oxygen/emergency support under the response protocol.','Stabilization takes priority over transporting paperwork.',['reaction.row.2'],{safety:true}),
      T('no-flush','Immediate response','Keep the blood-containing set from being flushed','Do not flush the attached blood-containing administration set into the patient.','A saline flush would push more of the implicated product into the patient.',['reaction.row.4'],{safety:true}),
      T('disconnect','Immediate response','Isolate/disconnect the implicated set safely','Using hand hygiene/PPE and aseptic technique, isolate/disconnect the implicated set according to the emergency/access protocol without losing needed access.','The source product must be separated while the patient remains supported.',['reaction.row.5'],{safety:true}),
      T('new-access','Immediate response','Maintain IV access with a safe new setup','Maintain needed access with new tubing and compatible 0.9% saline, or another IV access, as directed. Follow actual orders for fluids and rate.','The patient may need emergency medication or support through safe access.',['reaction.row.6'],{safety:true}),
      T('notify','Immediate response','Notify provider and transfusion service','Promptly report the component/unit, onset, symptoms, vital signs, volume infused and actions/response to the provider and transfusion service. Delegate notification while support continues when help is available.','Clinical treatment and the blood-bank investigation both need notification.',['reaction.row.3'],{safety:true}),
      T('check','Investigate and treat','Repeat patient/component checks','Repeat the identification/clerical checks and inspect the component, without delaying care.','A mismatch can identify a cause and further risk.',[]),
      T('preserve','Investigate and treat','Preserve and transport the bag, set and form','Preserve the product container and administration set with the required blood-bank documentation. Use the designated biohazard transport packaging and blood-bank return process, protecting sharps.','The blood bank may need the actual product and set for investigation.',['reaction.row.7']),
      T('blood-sample','Investigate and treat','Collect the directed fresh blood specimen','Obtain requested fresh blood samples with correct patient identification and bedside labeling. The manual specifies the opposite extremity; use the protocol-approved method that avoids contamination with transfused contents.','Sampling instructions depend on the investigation and available access.',['reaction.row.8']),
      T('urine','Investigate and treat','Collect urine if required','Collect and identify a urine specimen when ordered or required by the reaction protocol and arrange the requested testing/transport.','Not every suspected reaction requires identical specimens.',['reaction.row.9'],{conditional:true}),
      T('treat','Investigate and treat','Implement the reaction-specific orders','Give prescribed medications and other support using the appropriate checks. Do not independently restart the component; after a severe reaction it must not be restarted.','Anaphylaxis, hemolysis, overload and infection require different management.',['reaction.row.10'],{safety:true}),
      T('monitor','Continue care','Repeat observations frequently','Continue frequent vital signs, breathing/circulation checks, symptoms and fluid-balance monitoring under the response plan; escalate ongoing deterioration.','Improvement at one check does not establish sustained recovery.',['reaction.row.11'],{safety:true}),
      T('record','Continue care','Document and hand over','Record onset, component/unit, volume infused, time stopped, assessments, support, notifications, specimens/product disposition, orders and response; complete the required event report and handover.','A clear timeline supports continuing care and investigation.',[])
    ]
  };

  details.gtube = {
    scene: 'A patient with an established gastrostomy has several medications due and an enteral feeding plan. Rehearse the exact formulation, water and feed instructions supplied for the lab scenario. Use one medication/flush cycle at a time.',
    rows: [
      ...R('gt.assess',[42,42,42,42,'42–43',43,43,43,43,43,43,43],['Explain procedure','Stop feeding pump','Fowler position','Printed air-auscultation instruction, bowel sounds and abdominal/tolerance assessment','Aspirate/observe/measure residual','Residual return and pH testing; printed 5–10 mL and pH 1–4','Observe nausea and emesis','Inspect stoma for infection/leakage','Head of bed 30–45 degrees','Prescribed water flush before and after medications','Printed 30-minute post-medication feed hold','Printed head elevation about 60 minutes after feeding'],'Assessment section row'),
      ...R('gt.med',[43,44,44,44,44,44,44,44,44,44,'44–45',45,45,45,45,45],['Order/MAR comparison and six medication rights','Review acid-reducing medication/PPI use','Check whether each product may be crushed/given by tube','Do-not-crush forms: SL, sustained-release, long-acting, enteric-coated','Avoid touching medicine from multidose container','Pour/measure the correct dose','Split only appropriate scored tablets/use cutter','Crush each appropriate tablet separately; printed 30 mL mixing water','Keep several medications separate','Head of bed at least 30 degrees unless contraindicated','Liquid handling: shake as needed, asepsis, palm label, clean dripping lip','Measure liquid at eye level','Printed 30 mL warm-water before/after flush','Printed 15–30 mL between medications','Fowler position 30–60 minutes after medications','Document drug/dose/date/time/route/site and signature'],'Medication section row'),
      ...R('gt.header',[42,42],['Only crush suitable immediate-release products; liquid alternatives when suitable','Three-step medication administration checks'],'Header note','objective')
    ],
    notes: [
      {covers:['gt.header.1'],text:'Immediate-release does not automatically mean safe to crush. Check the exact product, tube route and pharmacy advice; use a suitable liquid/alternative when appropriate.'},
      {covers:['gt.header.2'],text:'Compare the product with the order/MAR during selection, preparation and immediately before administration, following the school’s three-check method.'}
    ],
    steps: [
      T('order','Prepare','Verify the order and medication rights','Compare each medication with the order/MAR: patient, medication, dose, route, time and documentation, plus allergies, indication and required assessment. Use the three medication checks.','A tube route does not replace normal medication checks.',['gt.med.1'],{safety:true}),
      T('acid','Prepare','Review acid reducers and feed interactions','Review gastric-acid reducers/PPIs and the feeding/suction plan. Verify each drug’s required separation from feeds and the actual tube-confirmation method.','Acid suppression can affect interpretation of aspirate pH, and feed interactions are drug-specific.',['gt.med.2']),
      T('form','Prepare','Check each formulation for tube suitability','Verify the actual product may be given through this tube and whether crushing/opening/dilution is permitted. Use a suitable liquid or obtain an alternative plan when necessary.','Not every oral product can be delivered safely by a tube.',['gt.med.3'],{safety:true}),
      T('do-not-crush','Prepare','Identify products that must not be crushed','Do not crush sublingual/buccal, sustained-/extended-release, long-acting or enteric-coated products without a pharmacist-verified appropriate alternative plan.','Changing the formulation can change release, absorption or the intended route.',['gt.med.4'],{safety:true}),
      T('gather','Prepare','Gather enteral supplies and the water plan','Gather separately labeled medicines, suitable enteral/ENFit syringes/adapters, approved crusher/cutter if needed, gloves and appropriate water. Verify dilution and flush volumes, water type and fluid restrictions.','Enteral connections and an individualized water plan help prevent wrong-route delivery and tube problems.',[]),
      T('no-touch','Prepare','Handle multidose medication aseptically','Clean hands and prepare one patient’s medicines in a clean area. Pour from a multidose container without touching the medication or contaminating the container.','Hands and preparation surfaces must not contaminate the dose.',['gt.med.5']),
      T('dose','Prepare','Prepare the correct amount','Calculate and pour/measure the prescribed dose, repeating the product/MAR and expiry/integrity checks.','Correct formulation with the wrong amount remains an error.',['gt.med.6'],{safety:true}),
      T('split','Prepare','Split tablets only when appropriate','If splitting is required and permitted for the exact product, use an appropriate scored tablet and a pill cutter. Do not assume an extended-release or other unsuitable tablet can be split.','A score line does not override a product-specific restriction.',['gt.med.7'],{conditional:true}),
      T('crush','Prepare','Prepare each suitable tablet separately','Finely crush each verified crushable tablet separately and disperse it in its approved water volume. The manual gives 30 mL per medicine; verify the actual drug/patient water plan.','Individual preparation avoids interactions and permits separate delivery.',['gt.med.8'],{conditional:true}),
      T('separate','Prepare','Keep all medications separate','Keep each prepared medicine in its own labeled preparation; do not combine several drugs or mix medicines into formula.','Drugs due together are not automatically compatible in one syringe.',['gt.med.9'],{safety:true}),
      T('liquid','Prepare','Handle liquid products correctly','For a liquid, shake when the product requires it, maintain asepsis, hold the bottle with the palm over its labeled side to protect the label from drips, and clean any dripping lip without contaminating the opening.','The dose and label need to remain reliable.',['gt.med.11'],{conditional:true}),
      T('measure','Prepare','Measure the liquid dose accurately','Use the appropriate calibrated enteral/oral measuring device. If using a medication cup, read its liquid level at eye level; choose an accurately sized syringe/adapter for a tube dose as directed.','A bottle estimate or an unsuitable measuring device can give the wrong amount.',['gt.med.12'],{conditional:true}),
      T('identify','At the bedside','Identify and explain','Perform hand hygiene, use two identifiers, confirm allergies, explain the procedure and provide privacy; use appropriate gloves for patient/tube assessment.','The prepared medicines must reach the correct patient.',['gt.assess.1'],{say:'I will give each medicine separately through your feeding tube and use the prescribed water flushes.',safety:true}),
      T('pause','At the bedside','Manage and pause the feeding','Pause/stop the feeding pump for administration as directed. Apply the verified medication-specific feed interruption and suction plan; do not impose the same hold on every drug.','Feed may interact with certain medicines and should not continue through the administration process.',['gt.assess.2']),
      T('position','At the bedside','Raise the head of the bed','Assist into the prescribed Fowler/semi-Fowler position, generally about 30–45 degrees unless contraindicated; follow the aspiration-prevention plan.','Positioning reduces aspiration risk.',['gt.assess.3','gt.assess.9','gt.med.10'],{safety:true}),
      T('abdomen','At the bedside','Assess abdomen and tolerance','Assess abdominal distention, bowel sounds as indicated, constipation, diarrhea and dehydration within the scenario. Do not treat bowel sounds or an air whoosh as proof of tube placement.','The manual combines abdominal assessment with an unreliable placement maneuver; keep the valid assessment separate.',['gt.assess.4'],{note:'Printed p. 42 row 4 includes injecting 10–30 mL of air and listening. That is not a reliable placement check; clarify the row with faculty.'}),
      T('tube','At the bedside','Verify tube readiness with a valid method','Inspect external position/mark and securement against the documented baseline and follow the actual tube’s approved readiness/confirmation protocol. Hold use for suspected displacement. Do not rely on air auscultation or residual volume as proof.','A mature gastrostomy and a newly inserted NG tube do not use identical confirmation requirements.',[],{safety:true}),
      T('residual','At the bedside','Address any prescribed residual assessment','If the actual tube/feeding protocol calls for residual assessment, aspirate by its method, observe and measure as directed. Do not make routine residual testing a universal medication prerequisite or placement proof.','Residual assessment and tube-position confirmation answer different questions.',['gt.assess.5'],{conditional:true}),
      T('ph','At the bedside','Use the approved aspirate/pH plan','Follow the actual protocol for aspirate return, any sample retained and pH interpretation. The manual lists withholding 5–10 mL and pH 1–4; do not use those numbers as universal clearance for every gastrostomy.','Tube type, baseline information, medication effects and the approved method matter.',['gt.assess.6'],{conditional:true}),
      T('nausea','At the bedside','Check nausea and vomiting','Ask about and observe nausea or emesis and assess new symptoms before proceeding. Hold/escalate concerning intolerance or aspiration signs.','Symptoms can identify a problem that a scheduled medication time does not override.',['gt.assess.7'],{say:'Have you had nausea, vomiting, or new abdominal discomfort?'}),
      T('stoma','At the bedside','Inspect the gastrostomy site','Assess the stoma for redness, drainage, infection signs, pain and leakage. Report concerning findings or suspected displacement before use.','Medication through a leaking/displaced tube can cause harm.',['gt.assess.8'],{safety:true}),
      T('flush-before','Give separately','Flush before medication','With hand hygiene/appropriate gloves and the correct enteral port/syringe, flush gently using the prescribed water/volume before the first drug. The manual’s preparation section says prescribed volume; its medication section gives 30 mL of warm water as an example. Verify the actual approved water type, temperature and volume. Do not force resistance.','The flush separates feed from medicine and checks a patent path.',['gt.assess.10','gt.med.13'],{safety:true}),
      T('give','Give separately','Administer one medication','Connect to the verified enteral port and deliver one prepared medication. Rinse the preparation container/crusher as directed and include that rinse in the prescribed dose/water plan.','Drug left in the container has not reached the patient.',[],{safety:true}),
      T('between','Give separately','Flush between every medication','Use the individualized ordered water volume between each medicine. The manual lists 15–30 mL. Repeat the one-medicine/flush cycle, keeping drugs separate.','A between-drug flush reduces contact between different medicines.',['gt.med.14'],{safety:true}),
      T('flush-after','Finish','Give the final flush and manage the tube','After the last medicine, give the prescribed final water flush and close/manage the tube as directed. Include all mixing, rinse and flush water in intake.','The final flush clears residual drug and maintains tube patency.',['gt.assess.10','gt.med.13']),
      T('feed-restart','Finish','Use the correct feed restart interval','Follow the verified interval for the actual medication and nutrition/suction plan. The printed assessment section says hold feeds for 30 minutes; that interval is not correct for every medication.','A premature restart can affect absorption, while unnecessary interruption reduces nutrition.',['gt.assess.11']),
      T('position-after','Finish','Maintain the required positioning','Maintain ordered head elevation/aspiration precautions. The manual says about 60 minutes after feeding and 30–60 minutes after medication; clarify which scenario-specific duration applies, particularly with continuous feeds.','Do not treat completion of medication delivery as permission to place the patient flat.',['gt.assess.12','gt.med.15']),
      T('record','Finish','Reassess, document and sign','Reassess tube patency, tolerance and medication effects. Remove supplies/gloves, clean hands and leave the patient safe. Record every medicine, dose, date/time, enteral route/site, water intake, feed changes, response and your required signature.','Both medicines and water/feed changes belong in the record.',['gt.med.16'])
    ]
  };

  details['trach-suction'] = {
    scene: 'An adult with a tracheostomy has findings suggesting retained secretions. Use the actual tube, approved shallow depth, catheter, suction setting and oxygen plan supplied in lab. Demonstrate an open-suction procedure and reassess before another pass.',
    rows: [
      ...R('suction.row',[67,67,67,67,67,67,67,67,68,68,68,68,68,68,68,68,68,68,68,68,69,69,69],['Assess suction need','Gather/assemble equipment','Explain procedure','Semi-Fowler position','Sterile gloves','Printed mouth-to-ear/jaw depth measurement','Attach suction tubing and set 80–120','Test suction apparatus','Hold at suction depth/turn machine on','Pour sterile saline into container','Gloved catheter handling at connection','Keep catheter part entering airway untouched','Printed 100% bag breaths before/between passes','Printed six-inch/cough insertion instruction','No suction/force during insertion; stop at predetermined depth','Maximum 15 seconds; at least 30 seconds between passes','Clear secretions by suctioning rinse solution through catheter','Restore oxygen between passes','Rinse tubing, stop suction machine and disconnect','Coil catheter and remove glove over it for disposal','Manage vacuum bottle, remove gloves and wash hands','Mouth care','Document procedure and response'],'Suction row'),
      ...R('trach.header',[67,67,67,67],['Goal: clear thick secretions not cleared by coughing','Objective: nasal, oral, pharyngeal and tracheostomy suctioning','Objective: provide tracheostomy care','Objective: recognize/report respiratory deviations'],'Header/goal','objective')
    ],
    notes: [
      {covers:['trach.header.1'],text:'Connect retained secretions with visible mucus, noisy breathing, ineffective cough, tachypnea or other assessed evidence; improvement in airway status is the outcome.'},
      {covers:['trach.header.2'],text:'The manual’s broad objective lists nasal/oral/pharyngeal routes too. This station rehearses tracheostomy suction. Confirm with faculty if another route will be demonstrated; oral measurements must not be reused as tracheostomy-depth instructions.'},
      {covers:['trach.header.3'],text:'The companion tracheostomy-care station covers the site, inner cannula, dressing and holder, including all 19 numbered care rows.'},
      {covers:['trach.header.4'],text:'Recognize deterioration such as desaturation, bradycardia/dysrhythmia, distress, bleeding or inability to ventilate. Stop and obtain appropriate airway support.'}
    ],
    steps: [
      T('need','Assess and prepare','Assess the need for suction','Perform hand hygiene and assess breathing, breath sounds, cough, visible mucus, oxygenation and relevant ventilator findings. Identify the actual airway and use two patient identifiers without delaying urgent support.','Suction treats an assessed airway need rather than simply completing a schedule.',['suction.row.1'],{safety:true}),
      T('gather','Assess and prepare','Gather and assemble the equipment','Check suction apparatus/tubing, appropriate sterile catheter/kit, prescribed oxygen/monitoring, PPE, rinse supplies and emergency airway equipment. Choose the catheter for this adult tube; the catheter should occlude less than half the artificial-airway lumen.','Preparation prevents searching for supplies with an unsupported airway.',['suction.row.2']),
      T('explain','Assess and prepare','Explain what the patient will feel','Explain the purpose and brief procedure, how the patient can signal distress, and what you will monitor. Provide privacy.','Communication can reduce fear and help detect intolerance.',['suction.row.3'],{say:'I will remove secretions briefly, restore your oxygen support and pause to check how you tolerate it.'}),
      T('position','Assess and prepare','Position for breathing and access','Place in semi-Fowler position as tolerated and consistent with the clinical plan; arrange the bed/work area safely.','Position should support breathing and safe access to the tube.',['suction.row.4']),
      T('depth','Assess and prepare','Determine the correct shallow depth','Use the identified tube and approved predetermined shallow-suction depth. Do not measure a tracheostomy catheter from mouth to ear/jaw or assume six inches for everyone.','External oral measurements do not establish this artificial airway’s length.',['suction.row.6'],{safety:true,note:'Clarify the printed oral measurement and six-inch/cough wording with faculty using the actual trach tube.'}),
      T('pressure','Assess and prepare','Connect and set the suction','Attach tubing, set the prescribed/local adult pressure and keep it as low as effectively clears secretions. The manual lists 80–120 mm Hg; AARC’s adult magnitude limit below 200 is an upper bound, not a target.','Excess pressure can increase trauma and impair ventilation.',['suction.row.7'],{safety:true}),
      T('test','Assess and prepare','Test the apparatus and ready the machine','Test that the suction apparatus functions and the pressure is correctly set using the device procedure. Turn it on/ready it for use and preserve the predetermined depth reference.','A connected but untested machine can fail when the catheter is already in the airway.',['suction.row.8','suction.row.9']),
      T('rinse-setup','Assess and prepare','Prepare sterile rinse solution if used','Prepare the sterile rinse container/solution required by the equipment protocol without contaminating it. It is for catheter/tubing clearing, not routine instillation into the airway.','Rinsing equipment and pouring fluid into a tracheostomy are different actions.',['suction.row.10']),
      T('oxygen','Assess and prepare','Preoxygenate with the approved method','Preoxygenate using the patient’s prescribed oxygen/ventilator method and trained assistance as needed. Do not replace that plan with routine forceful bag hyperventilation.','Preoxygenation protects against loss of oxygen during suction.',['suction.row.13'],{safety:true,note:'The printed row describes 100% bag breaths two or three times. Faculty must identify the approved method for this patient and equipment.'}),
      T('sterile','Perform and recover','Clean hands, apply PPE and sterile gloves','Perform hand hygiene and required exposure PPE. For open artificial-airway suction, set up and maintain sterile technique and don sterile gloves.','The part entering the airway must remain sterile.',['suction.row.5'],{safety:true}),
      T('handle','Perform and recover','Handle and connect the catheter correctly','Keep the sterile dominant hand on the catheter and use the other hand for nonsterile tubing/control tasks as appropriate to the kit. Connect without contaminating the part that will enter the airway.','Separating hand roles protects the sterile catheter.',['suction.row.11','suction.row.12'],{safety:true}),
      T('insert','Perform and recover','Insert gently without suction','Insert gently without applying suction to the approved shallow depth. Stop at that depth and do not force resistance or routinely advance deeply to provoke coughing. Deep suction is reserved for ineffective shallow suction under the plan.','Suction during insertion and unnecessary deep advancement increase harm.',['suction.row.14','suction.row.15'],{safety:true}),
      T('withdraw','Perform and recover','Apply suction during withdrawal briefly','Apply suction during withdrawal using the catheter technique and monitor the patient. Keep each suctioning procedure no longer than 15 seconds and as brief as effective.','Prolonged suction can worsen hypoxemia and dysrhythmia.',['suction.row.16'],{safety:true}),
      T('restore','Perform and recover','Restore respiratory support and allow recovery','Restore the prescribed oxygen/ventilator support between passes. Allow at least the manual’s 30-second recovery interval and longer until the patient has recovered under the plan. Stop/escalate deterioration rather than completing a set number of passes.','The patient’s recovery matters more than a timer alone.',['suction.row.16','suction.row.18'],{safety:true}),
      T('clear','Perform and recover','Clear the catheter as the system permits','If the catheter/equipment protocol permits another use within this procedure, clear secretions with the approved sterile rinse solution and preserve the required technique. Do not routinely instill saline into the airway.','A contaminated or inappropriately reused catheter is not made safe by rinsing.',['suction.row.17']),
      T('reassess','Perform and recover','Reassess before another pass','Reassess breath sounds, secretion clearance, work of breathing, heart rate and oxygenation before deciding whether suction is still required. Obtain urgent airway help for unresolved obstruction or deterioration.','Another pass is a clinical decision, not an automatic repetition.',[],{safety:true}),
      T('end-system','Finish','Manage the tubing and turn off the machine','At completion, rinse/manage the suction tubing as its instructions require, stop the suction machine and disconnect/dispose of the open catheter according to protocol.','Equipment handling must not recontaminate the patient or work area.',['suction.row.19']),
      T('catheter-disposal','Finish','Contain the used catheter','For the manual’s open single-use technique, coil the catheter in the dominant gloved hand and remove the glove over the coil for contained disposal in the designated receptacle.','Containing the secretions reduces environmental contamination.',['suction.row.20']),
      T('canister','Finish','Manage the canister and clean hands','Manage/empty or replace the collection canister only as its closed-system/device policy permits and as needed; prevent splashes. Remove remaining gloves/PPE and perform hand hygiene.','Canister handling is another exposure risk.',['suction.row.21']),
      T('mouth','Finish','Provide mouth care','Provide oral care using the appropriate technique and precautions after airway suctioning.','Secretions and oral contamination still need attention after the airway pass.',['suction.row.22']),
      T('record','Finish','Document the procedure and response','Reassess and leave prescribed respiratory support in place and the patient safe. Record indication, technique/depth/settings as required, number of passes, secretion characteristics, oxygenation/tolerance, response and escalation.','The desired outcome is improved airway status with a tolerated procedure.',['suction.row.23'])
    ]
  };

  details['trach-care'] = {
    scene: 'A patient’s tracheostomy site, dressing and inner cannula need care. Identify the actual device, reusable versus disposable pathway, respiratory-support needs and trained assistance before starting. Routine site care does not remove the outer tracheostomy tube.',
    rows: R('care.row',[69,69,69,69,69,69,69,69,69,70,70,70,70,70,70,70,70,70,70],['Chest towel/linen-saver','Loosen caps of printed peroxide and saline solutions','Hand washing/clean glove for dirty phase','Discard soiled dressing then gloves','Assess site erosion/wound problems','Equipment on over-bed table','Open sterile care tray using sterile technique','Separate applicators, 4×4 gauze, split dressing and ties','Printed three-container preparation with 1:1 peroxide/saline, rinse saline and moistened gauze','Unlock/remove inner cannula with nondominant hand','Discard disposable or soak reusable in printed peroxide/saline','Brush a reusable cannula','Rinse reusable cannula in sterile saline','Dry/replace inner cannula and resume ordered oxygen','Clean neck plate/outer surface with applicators','Saline gauze stoma cleansing and printed clock-face strokes','Dry and apply sterile split dressing','Keep old/new ties secure, printed fit/head-position wording','Dispose, hand hygiene and documentation'],'Care row'),
    notes: [],
    steps: [
      T('identify','Assess and prepare','Identify the patient, airway and device','Perform hand hygiene, use two identifiers, review the care plan, assess breathing/oxygenation, secretions, tube security and stoma, and identify tube model, inner-cannula type and airway age/risk.','The wrong cannula pathway or an insecure airway can make routine care dangerous.',[],{safety:true}),
      T('support','Assess and prepare','Arrange help and respiratory support','Explain the procedure, provide privacy and position as tolerated. Ensure emergency supplies and trained assistance for high-risk care/holder changes. Plan how prescribed oxygen/ventilation will be maintained during cannula handling; have the correct replacement ready.','Do not create a gap in necessary ventilation while looking for a part.',[],{say:'I will clean the area and the correct inner tube while keeping your breathing tube secure.',safety:true}),
      T('pad','Assess and prepare','Protect the chest and arrange equipment','Place a towel or linen-saver over the chest and arrange equipment within reach on the cleaned over-bed work area.','A reachable organized field avoids leaving an unsecured airway.',['care.row.1','care.row.6']),
      T('solutions','Assess and prepare','Verify solutions and loosen approved caps','Check the exact device’s cleaning instructions and the approved site-care solution, then loosen the caps needed for aseptic pouring. The manual names peroxide and saline; peroxide is not universal for every tube or stoma.','Preparation must match the supplied device rather than the chemical names alone.',['care.row.2'],{note:'Ask faculty which inner cannula, cleaning solution, brushing and drying method apply to this station.'}),
      T('dirty-hands','Dirty phase','Clean hands and put on clean gloves','Perform hand hygiene and put on clean gloves/PPE for the soiled-dressing phase. Keep hand roles appropriate to the care protocol.','Removing contaminated material should not contaminate the later sterile phase.',['care.row.3']),
      T('dressing-off','Dirty phase','Remove and discard the soiled dressing','Stabilize the tube as required; remove and discard the soiled dressing in the designated receptacle. Assess drainage, then remove contaminated gloves and clean hands.','A dirty glove must not move into the clean/aseptic phase.',['care.row.4']),
      T('inspect','Dirty phase','Inspect the stoma and surrounding skin','Assess for erosion, breakdown, redness, drainage, bleeding or leakage and report significant findings.','The dressing can conceal tissue injury or infection signs.',['care.row.5']),
      T('tray','Aseptic care','Open the required care tray/field','Open the sterile tracheostomy tray/field using aseptic technique and apply the gloves/technique required for acute-care site and cannula care.','A sterile package is useful only while its contents remain protected.',['care.row.7'],{safety:true}),
      T('kit','Aseptic care','Separate and arrange the kit supplies','Arrange the applicators, 4×4 gauze, separate pre-cut fenestrated/split dressing and the correct replacement holder/ties. The manual lists two applicator packages; use the actual kit/procedure’s required quantity.','Wet/dirty supplies should not contaminate the new dressing or ties.',['care.row.8']),
      T('basins','Aseptic care','Prepare the approved containers and gauze','Prepare the approved reusable-cannula cleaning/rinse containers and saline-moistened gauze as needed, maintaining asepsis. The printed row describes a 1:1 peroxide/saline basin, saline rinse basin and third gauze container; use that chemistry only if the actual instructions approve it.','A device-specific cleaning method can differ from the manual’s example.',['care.row.9']),
      T('remove','Aseptic care','Stabilize and remove the inner cannula','Stabilize the outer tube/neck plate and follow the device’s unlock/removal method, using the nondominant/contaminated hand role as directed. Maintain the respiratory-support plan. Do not remove the outer tube for routine cleaning.','Accidental outer-tube displacement can lose the airway.',['care.row.10'],{safety:true}),
      T('pathway','Aseptic care','Choose disposable replacement or reusable cleaning','Discard a disposable single-use inner cannula and replace it with the correct new part. For a reusable cannula, follow only its approved cleaning/soaking procedure, with an immediate clean replacement/support plan when the device requires it.','Disposable parts must not be cleaned for reuse.',['care.row.11'],{safety:true}),
      T('brush','Aseptic care','Clean a reusable cannula only as allowed','If reusable, remove debris using only the manufacturer-approved method and permitted brush/tool. Do not brush a part whose instructions prohibit it.','Inappropriate tools can damage the cannula.',['care.row.12'],{conditional:true}),
      T('rinse','Aseptic care','Rinse the reusable cannula as directed','If reusable, rinse using the solution and technique specified by its instructions; the manual gives sterile saline.','The rinse must remove debris/cleaning solution without harming the part.',['care.row.13'],{conditional:true}),
      T('replace','Aseptic care','Dry/replace, lock and restore support','Dry the reusable cannula as its instructions require or use the correct new replacement. Reinsert/lock securely using the actual device method, restore/confirm prescribed oxygen/ventilator connections and assess airflow/tolerance.','A wrong or unlocked part can impair ventilation.',['care.row.14'],{safety:true}),
      T('plate','Aseptic care','Clean the neck plate and outer surfaces','Using the approved applicators/solution and technique, clean the neck plate and accessible outer surfaces while keeping the tube stable.','Site cleaning does not mean taking the outer tube out.',['care.row.15']),
      T('stoma','Aseptic care','Clean the stoma with fresh strokes','Use the approved saline-moistened gauze/site technique and a fresh clean surface for each outward stroke. A common clock-face pattern uses fresh gauze for 12→3, 12→9, 3→6 and 9→6; the manual names 12→3 and 9→6. Cover the whole site under the approved protocol without dragging dirty material back toward the opening.','The purpose of the stroke pattern is effective cleaning without recontamination.',['care.row.16']),
      T('dress','Finish','Dry and apply the correct split dressing','Pat the area dry and apply the approved sterile pre-cut, non-fraying fenestrated/split dressing when indicated, touching protected edges. Do not cut ordinary gauze near the airway.','Moisture harms skin and loose fibers can enter the airway.',['care.row.17']),
      T('holder','Finish','Maintain security during holder/tie care','Keep the tube continuously secured/stabilized with trained assistance as required. Retain old security until replacement security is established when the holder design permits. Fit the new holder by the device/local instructions and reassess comfort/skin.','The printed tight tie, flexed head and one-finger wording is not a universal fit rule.',['care.row.18'],{safety:true}),
      T('finish','Finish','Dispose, clean hands, reassess and document','Discard supplies appropriately, remove gloves/PPE and wash/clean hands. Reassess airway patency, tube/holder security, oxygenation, skin and comfort; leave the patient safe. Document the care, cannula pathway, supplies/solution, findings, tolerance and response.','The final outcome is a patent secure airway and cared-for skin.',['care.row.19'])
    ]
  };

  function apply(data) {
    if (!data || data.detailedCheckoffs) return data;
    data.refs.components = { title: 'Lifeblood · Use of blood components and indications', url: 'https://www.lifeblood.com.au/health-professionals/clinical-practice/use-of-blood-components' };
    data.stations.find(s => s.id === 'blood').refs.push('components');
    data.legacySteps = data.stations.flatMap(s => s.steps).map(s => Object.assign({}, s));
    data.sourceRows = Object.values(details).flatMap(d => d.rows);
    for (const st of data.stations) {
      const d = details[st.id];
      if (!d) {
        // The manual has no secondary-infusion procedure: retain the explicitly marked supplement.
        st.steps = st.steps.map((s, i) => Object.assign({}, s, { id: st.id + ':detail-' + s.id.split(':').pop(), phase: i < 3 ? 'Prepare' : i < 8 ? 'Set up and start' : 'Finish', covers: [], added: true }));
        st.requirements = []; st.learningNotes = [];
        st.scene = 'Use the lab’s actual medication order, compatible primary fluid and pump/tubing instructions. This is the supplemental secondary-infusion flow; faculty must confirm what the IV test-off requires.';
        continue;
      }
      st.scene = d.scene; st.requirements = d.rows; st.learningNotes = d.notes;
      st.steps = d.steps.map(s => Object.assign({}, s, { id: st.id + ':detail-' + s.key, added: !s.covers.length }));
      const vivaTitles = { ivpush: ['Explain accuracy checks','Explain adverse-effect monitoring','Explain relevant laboratory checks','Explain last-dose and authorized titration checks'], blood: ['Describe the complete transfusion demonstration','Explain component indications','Explain the individual compatibility checks','Explain reactions and their consequences'], gtube: ['Explain formulation suitability','Explain the three medication checks'], 'trach-suction': ['Explain the purpose and indications','Distinguish the suction routes named in the objective','Describe the companion trach-care procedure','Explain respiratory changes that require reporting'] };
      d.notes.forEach((n,i) => st.steps.push({ id: st.id + ':detail-viva-' + (i+1), phase: 'Explain when asked', title: vivaTitles[st.id][i], action: n.text, why: 'This is a printed header, goal or learning objective. Practice explaining it as well as demonstrating the numbered procedure rows.', covers: n.covers.slice(), safety: false, viva: true, added: false }));
    }
    data.detailedCheckoffs = true; data.checked = '2026-11-02';
    data.coverage = { numberedRows: data.sourceRows.filter(r => r.kind === 'row').length, headerNotes: data.sourceRows.filter(r => r.kind !== 'row').length, steps: data.stations.reduce((n, s) => n + s.steps.length, 0) };
    return data;
  }
  return { apply, details };
});
